{"tool": "brick.build", "input": {"seed": 1, "code": "script({
  title: "Piplup — Sinnoh Water-Type Starter",
  description: "Large-scale sculpted Piplup with 3-pronged light-blue crown, conical beak, white chest buttons, dark-blue cape & tail, waving flipper, Bubble Beam water vortex, Sinnoh ice crystals, and Poke Ball with Berries.",
  palette: {
    body: "medium azure",
    head: "blue",
    cape: "dark blue",
    belly: "white",
    beak: "yellow",
    foot: "bright light orange",
    eye: "black",
    water: "trans light blue",
    ice: "trans-clear",
    pokeball: "red",
    leaf: "lime"
  }
});

const PART_DIMS = {
  "3005": [1, 1, 3],
  "3004": [2, 1, 3],
  "3622": [3, 1, 3],
  "3010": [4, 1, 3],
  "3003": [2, 2, 3],
  "3002": [3, 2, 3],
  "3001": [4, 2, 3],
  "3024": [1, 1, 1],
  "3023b": [2, 1, 1],
  "3623": [3, 1, 1],
  "3710": [4, 1, 1],
  "3666": [6, 1, 1],
  "3022": [2, 2, 1],
  "3021": [3, 2, 1],
  "3020": [4, 2, 1],
  "3795": [6, 2, 1],
  "3031": [4, 4, 1],
  "3032": [6, 4, 1],
  "3035": [8, 4, 1],
  "30357": [3, 3, 1],
  "30565": [4, 4, 1],
  "41769a": [2, 4, 1],
  "41770a": [2, 4, 1],
  "3070b": [1, 1, 1],
  "3069b": [2, 1, 1],
  "63864": [3, 1, 1],
  "2431": [4, 1, 1],
  "3068b": [2, 2, 1],
  "87079": [4, 2, 1],
  "98138": [1, 1, 1],
  "25269": [1, 1, 1],
  "24246": [1, 1, 1],
  "14769": [2, 2, 1],
  "27925": [2, 2, 1],
  "54200": [1, 1, 2],
  "85984": [2, 1, 2],
  "3040b": [1, 2, 3],
  "3039": [2, 2, 3],
  "3298": [2, 3, 3],
  "3665a": [1, 2, 3],
  "3660b": [2, 2, 3],
  "3747b": [2, 3, 3],
  "24201": [1, 2, 4],
  "11477": [1, 2, 3],
  "15068": [2, 2, 3],
  "50950": [1, 3, 3],
  "61678": [1, 4, 3],
  "93273": [1, 4, 4],
  "88930": [4, 2, 3],
  "6091": [1, 2, 4],
  "3062b": [1, 1, 3],
  "3941": [2, 2, 3],
  "6141": [1, 1, 1],
  "4032b": [2, 2, 1],
  "4589": [1, 1, 3],
  "3942c": [2, 2, 6],
  "4740": [2, 2, 1],
  "3960": [4, 4, 2],
  "30385": [1, 1, 5],
  "30153": [1, 1, 3]
};

const occupied = new Set();
let totalPlaced = 0;
const TARGET_PLACED = 930;

function reserveVolume(x, y, z, w, h, d) {
  const rx = Math.round(x), ry = Math.round(y), rz = Math.round(z);
  const rw = Math.round(w), rh = Math.round(h), rd = Math.round(d);
  for (let ix = rx; ix < rx + rw; ix++) {
    for (let iy = ry; iy < ry + rh; iy++) {
      for (let iz = rz; iz < rz + rd; iz++) {
        occupied.add(ix + "," + iy + "," + iz);
      }
    }
  }
}

function canFit(x, y, z, w, h, d) {
  for (let ix = x; ix < x + w; ix++) {
    for (let iy = y; iy < y + h; iy++) {
      for (let iz = z; iz < z + d; iz++) {
        if (occupied.has(ix + "," + iy + "," + iz)) return false;
      }
    }
  }
  return true;
}

function p(part, at, colour, turn = 0) {
  const dims = PART_DIMS[part];
  if (!dims) return null;
  const t = ((turn % 360) + 360) % 360;
  const w = (t === 90 || t === 270) ? dims[1] : dims[0];
  const d = (t === 90 || t === 270) ? dims[0] : dims[1];
  const h = dims[2];
  const x = Math.round(at[0]);
  const y = Math.round(at[1]);
  const z = Math.round(at[2]);
  if (y < 0) return null;
  if (!canFit(x, y, z, w, h, d)) return null;
  reserveVolume(x, y, z, w, h, d);
  totalPlaced++;
  return place({ part, at: [x, y, z], colour, turn: t });
}

function pMirrorX(part, at, colour, turn = 0) {
  const dims = PART_DIMS[part];
  if (!dims) return [];
  const t = ((turn % 360) + 360) % 360;
  const w = (t === 90 || t === 270) ? dims[1] : dims[0];
  const mx = -Math.round(at[0]) - w;
  let mt = t;
  if (t === 90) mt = 270;
  else if (t === 270) mt = 90;
  return [
    p(part, at, colour, t),
    p(part, [mx, at[1], at[2]], colour, mt)
  ];
}

// Reserve massing core volumes upfront so placed parts never cut massing
const TORSO_BOX = { at: [-4, 6, -3], size: [8, 21, 6], colour: "medium azure", interior: "empty" };
const NECK_BOX  = { at: [-4, 27, -3], size: [8, 6, 6], colour: "dark blue", interior: "empty" };
const HEAD_BOX  = { at: [-5, 33, -4], size: [10, 21, 8], colour: "blue", interior: "empty" };
reserveVolume(-4, 6, -3, 8, 21, 6);
reserveVolume(-4, 27, -3, 8, 6, 6);
reserveVolume(-5, 33, -4, 10, 21, 8);

// ============================================================================
// SECTION 1: PIPLUP WEBBED FEET & ANKLES (y = 0 .. 6)
// ============================================================================
const feetOps = [];

// Left foot (x = -7..-2) & Right foot (x = 1..6), mirrored across X = 0
// Layer y = 0: Wide webbed foot pads + 3 splayed toes
feetOps.push(...pMirrorX("3020", [-6, 0, -5], "bright light orange", 90)); // 2x4 along Z
feetOps.push(...pMirrorX("3020", [-4, 0, -5], "bright light orange", 90));
feetOps.push(...pMirrorX("3023b", [-7, 0, -5], "yellow", 90));
feetOps.push(...pMirrorX("3023b", [-7, 0, -3], "bright light orange", 90));
feetOps.push(...pMirrorX("3023b", [-2, 0, -5], "yellow", 90));
feetOps.push(...pMirrorX("3023b", [-2, 0, -3], "bright light orange", 90));
feetOps.push(...pMirrorX("3020", [-6, 0, -1], "bright light orange", 0));
feetOps.push(...pMirrorX("3022", [-5, 0, 1], "bright light orange", 0));

// Three forward toes at z = -8 .. -6
feetOps.push(...pMirrorX("3023b", [-7, 0, -7], "yellow", 90)); // Outer toe
feetOps.push(...pMirrorX("3022", [-5, 0, -8], "yellow", 0));   // Middle long toe
feetOps.push(...pMirrorX("3023b", [-2, 0, -7], "yellow", 90)); // Inner toe

// Layer y = 1..3: Sculpted toes, rounded claws, and webbed instep slopes
feetOps.push(...pMirrorX("24246", [-7, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("54200", [-7, 1, -6], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-5, 1, -8], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-4, 1, -8], "yellow", 0));
feetOps.push(...pMirrorX("15068", [-5, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-2, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("54200", [-2, 1, -6], "yellow", 0));

// Mid-foot arch & heel (y = 1..3)
feetOps.push(...pMirrorX("11477", [-7, 1, -5], "bright light orange", 0));
feetOps.push(...pMirrorX("11477", [-2, 1, -5], "bright light orange", 0));
feetOps.push(...pMirrorX("3003", [-5, 1, -4], "bright light orange", 0));
feetOps.push(...pMirrorX("3004", [-5, 1, -2], "bright light orange", 0));
feetOps.push(...pMirrorX("11477", [-6, 1, -3], "yellow", 90));
feetOps.push(...pMirrorX("11477", [-3, 1, -3], "yellow", 270));
feetOps.push(...pMirrorX("15068", [-5, 1, -1], "bright light orange", 180));
feetOps.push(...pMirrorX("3069b", [-5, 1, 1], "bright light orange", 0));

// Ankle columns & lower leg transition (y = 4..5)
feetOps.push(...pMirrorX("3660b", [-5, 3, -5], "medium azure", 0));
feetOps.push(...pMirrorX("3660b", [-6, 3, -3], "medium azure", 90));
feetOps.push(...pMirrorX("3660b", [-3, 3, -3], "medium azure", 270));
feetOps.push(...pMirrorX("3660b", [-5, 3, -1], "dark blue", 180));
feetOps.push(...pMirrorX("3022", [-5, 4, -3], "medium azure", 0));
feetOps.push(...pMirrorX("3022", [-5, 5, -3], "medium azure", 0));

section("Piplup Feet and Ankles", feetOps);

// ============================================================================
// SECTION 2: PIPLUP PLUMP TORSO, WHITE CHEST BUTTONS & TAIL CAPE (y = 6 .. 26)
// ============================================================================
const torsoOps = [box(TORSO_BOX)];

// Lower belly & hip undercut (y = 6..9)
for (let x = -4; x <= 2; x += 2) {
  torsoOps.push(p("3660b", [x, 6, -5], "medium azure", 0));
  torsoOps.push(p("3660b", [x, 6, 3], "dark blue", 180));
}
torsoOps.push(...pMirrorX("24201", [-5, 6, -5], "medium azure", 0));
torsoOps.push(...pMirrorX("24201", [-5, 6, 3], "dark blue", 180));
for (let z = -3; z <= 1; z += 2) {
  torsoOps.push(...pMirrorX("3660b", [-6, 6, z], "medium azure", 90));
}
// Crotch / lower belly bridge between legs at y = 5..8
torsoOps.push(p("3660b", [-1, 5, -4], "medium azure", 0));
torsoOps.push(p("3660b", [-1, 5, 0], "dark blue", 180));
torsoOps.push(p("15068", [-1, 4, -2], "medium azure", 0));

// Plump lower & mid belly front shell (y = 9..17, z = -6..-4)
for (let y = 9; y <= 15; y += 3) {
  torsoOps.push(p("3001", [-2, y, -5], "medium azure", 0));
  torsoOps.push(...pMirrorX("3003", [-4, y, -5], "medium azure", 0));
  torsoOps.push(...pMirrorX("11477", [-6, y, -5], "medium azure", 90));
  torsoOps.push(...pMirrorX("11477", [-6, y, -4], "medium azure", 90));
}
// Extra rounded front tummy bulge at z = -6 (y = 10..17)
torsoOps.push(p("88930", [-2, 9, -6], "medium azure", 180));
torsoOps.push(...pMirrorX("11477", [-4, 9, -6], "medium azure", 90));
for (let y = 12; y <= 15; y += 3) {
  torsoOps.push(p("3010", [-2, y, -6], "medium azure", 0));
  torsoOps.push(...pMirrorX("11477", [-4, y, -6], "medium azure", 90));
}
torsoOps.push(p("2431", [-2, 18, -6], "medium azure", 0));

// Signature Two White Chest Buttons (y = 18..22, z = -6..-5)
// Left button at x = -4..-3, Right button at x = 2..3
torsoOps.push(...pMirrorX("3003", [-4, 18, -5], "white", 0));
torsoOps.push(...pMirrorX("3022", [-4, 21, -5], "white", 0));
torsoOps.push(...pMirrorX("25269", [-4, 18, -6], "white", 0));
torsoOps.push(...pMirrorX("25269", [-3, 18, -6], "white", 270));
torsoOps.push(...pMirrorX("3022", [-4, 19, -6], "white", 0));
torsoOps.push(...pMirrorX("14769", [-4, 20, -6], "white", 0));
torsoOps.push(...pMirrorX("98138", [-4, 21, -6], "white", 0));
torsoOps.push(...pMirrorX("98138", [-3, 21, -6], "white", 0));
torsoOps.push(...pMirrorX("85984", [-4, 22, -5], "white", 0));

// Center chest between the two white spots + cape V-neck tip (x = -2..1, y = 18..23)
torsoOps.push(p("3001", [-2, 18, -5], "medium azure", 0));
torsoOps.push(p("3023b", [-2, 19, -6], "medium azure", 90));
torsoOps.push(p("3023b", [1, 19, -6], "medium azure", 90));
torsoOps.push(p("3069b", [-2, 20, -6], "medium azure", 90));
torsoOps.push(p("3069b", [1, 20, -6], "medium azure", 90));
// Dark blue V-point of cape collar dipping between the white spots
torsoOps.push(p("3022", [-1, 19, -6], "dark blue", 0));
torsoOps.push(p("3068b", [-1, 20, -6], "dark blue", 0));
torsoOps.push(p("3003", [-1, 21, -5], "dark blue", 0));
torsoOps.push(...pMirrorX("3024", [-2, 21, -5], "white", 0)); // White collar trim
torsoOps.push(...pMirrorX("54200", [-2, 22, -5], "white", 0));
torsoOps.push(...pMirrorX("11477", [-5, 18, -5], "medium azure", 90));
torsoOps.push(...pMirrorX("11477", [-5, 21, -5], "dark blue", 90));

// Rounded Flanks (x = -7..-5 and x = 4..6, y = 9..21, z = -3..2)
for (let y = 9; y <= 18; y += 3) {
  // Front half of flank in medium azure
  torsoOps.push(...pMirrorX("3003", [-6, y, -3], "medium azure", 0));
  torsoOps.push(...pMirrorX("15068", [-7, y, -3], "medium azure", 90));
  // Back half of flank in dark blue (cape edge)
  torsoOps.push(...pMirrorX("3003", [-6, y, -1], "dark blue", 0));
  torsoOps.push(...pMirrorX("15068", [-7, y, -1], "dark blue", 90));
  torsoOps.push(...pMirrorX("3003", [-6, y, 1], "dark blue", 0));
  torsoOps.push(...pMirrorX("11477", [-7, y, 1], "dark blue", 90));
  torsoOps.push(...pMirrorX("11477", [-7, y, 2], "dark blue", 90));
}

// Back Cape & 3-Feathered Penguin Tail (z = 3..8, y = 8..26)
// Tail underside support at y = 8..11
torsoOps.push(p("3747b", [-1, 8, 3], "dark blue", 180));
torsoOps.push(...pMirrorX("3660b", [-3, 8, 3], "dark blue", 180));
torsoOps.push(...pMirrorX("24201", [-4, 8, 3], "dark blue", 180));
torsoOps.push(p("3660b", [-1, 11, 5], "medium azure", 180));
torsoOps.push(...pMirrorX("3665a", [-2, 11, 4], "dark blue", 180));

// Three Sculpted Tail Plumes (y = 11..16, z = 3..8)
// Center plume (medium azure & blue, longest to z = 8)
torsoOps.push(p("3003", [-1, 11, 3], "dark blue", 0));
torsoOps.push(p("61678", [-1, 14, 4], "medium azure", 180));
torsoOps.push(p("61678", [0, 14, 4], "medium azure", 180));
torsoOps.push(p("15068", [-1, 17, 4], "blue", 180));
// Left & Right outer tail plumes (dark blue, splaying to z = 7)
torsoOps.push(...pMirrorX("3003", [-3, 11, 3], "dark blue", 0));
torsoOps.push(...pMirrorX("50950", [-3, 14, 4], "dark blue", 180));
torsoOps.push(...pMirrorX("50950", [-2, 14, 4], "dark blue", 180));
torsoOps.push(...pMirrorX("11477", [-4, 11, 3], "dark blue", 180));
torsoOps.push(...pMirrorX("11477", [-4, 14, 3], "dark blue", 180));

// Upper Back Cape (y = 17..26, z = 3..5)
for (let y = 17; y <= 23; y += 3) {
  torsoOps.push(p("3003", [-1, y, 3], "blue", 0)); // Subtle royal blue cape center ridge
  torsoOps.push(...pMirrorX("3003", [-3, y, 3], "dark blue", 0));
  torsoOps.push(...pMirrorX("11477", [-5, y, 3], "dark blue", 90));
  torsoOps.push(...pMirrorX("11477", [-5, y, 4], "dark blue", 90));
  torsoOps.push(...pMirrorX("15068", [-3, y, 4], "dark blue", 180));
}

section("Piplup Torso, Belly, and Tail", torsoOps);

// ============================================================================
// SECTION 3: PIPLUP CAPE COLLAR & ASYMMETRIC FLIPPERS (y = 12 .. 34)
// ============================================================================
const collarAndFlipperOps = [box(NECK_BOX)];

// Dark-blue Cape Collar / Shoulder Ruff (y = 24..30)
// Front V-collar & white trim
collarAndFlipperOps.push(p("3003", [-1, 24, -5], "dark blue", 0));
collarAndFlipperOps.push(...pMirrorX("3003", [-3, 24, -5], "dark blue", 0));
collarAndFlipperOps.push(...pMirrorX("15068", [-5, 24, -5], "dark blue", 0));
collarAndFlipperOps.push(p("15068", [-1, 27, -5], "dark blue", 0));
collarAndFlipperOps.push(...pMirrorX("15068", [-3, 27, -5], "dark blue", 0));
collarAndFlipperOps.push(...pMirrorX("11477", [-4, 27, -5], "white", 0)); // White collar highlight

// Shoulder & back collar mantle (y = 24..30, z = -3..5)
for (let z = -3; z <= 1; z += 2) {
  collarAndFlipperOps.push(...pMirrorX("3003", [-6, 21, z], "dark blue", 0));
  collarAndFlipperOps.push(...pMirrorX("15068", [-6, 24, z], "dark blue", 90));
  collarAndFlipperOps.push(...pMirrorX("15068", [-5, 27, z], "dark blue", 90));
}
collarAndFlipperOps.push(p("88930", [-2, 26, 3], "dark blue", 180));
collarAndFlipperOps.push(...pMirrorX("15068", [-4, 26, 3], "dark blue", 180));
collarAndFlipperOps.push(p("88930", [-2, 29, 3], "dark blue", 180));
collarAndFlipperOps.push(...pMirrorX("27925", [-4, 29, 3], "dark blue", 180));

// LEFT FLIPPER (x = -11 .. -6, y = 12 .. 25, z = -3 .. 2) — Angled Downward
collarAndFlipperOps.push(p("3660b", [-8, 19, -2], "medium azure", 90));
collarAndFlipperOps.push(p("3660b", [-8, 19, 0], "medium azure", 90));
collarAndFlipperOps.push(p("15068", [-8, 22, -2], "dark blue", 90));
collarAndFlipperOps.push(p("15068", [-8, 22, 0], "dark blue", 90));
collarAndFlipperOps.push(p("3660b", [-9, 16, -2], "medium azure", 90));
collarAndFlipperOps.push(p("3660b", [-9, 16, 0], "medium azure", 90));
collarAndFlipperOps.push(p("15068", [-9, 19, -2], "medium azure", 90));
collarAndFlipperOps.push(p("15068", [-9, 19, 0], "medium azure", 90));
collarAndFlipperOps.push(p("24201", [-10, 12, -2], "medium azure", 90));
collarAndFlipperOps.push(p("24201", [-10, 12, -1], "medium azure", 90));
collarAndFlipperOps.push(p("24201", [-10, 12, 0], "medium azure", 90));
collarAndFlipperOps.push(p("15068", [-10, 16, -2], "medium azure", 90));
collarAndFlipperOps.push(p("11477", [-10, 16, 0], "medium azure", 90));
collarAndFlipperOps.push(p("25269", [-10, 15, -3], "white", 0));
collarAndFlipperOps.push(p("54200", [-9, 18, -3], "medium azure", 0));

// RIGHT FLIPPER (x = 5 .. 11, y = 21 .. 34, z = -4 .. 1) — Raised High in Wave!
collarAndFlipperOps.push(p("3660b", [6, 21, -2], "medium azure", 270));
collarAndFlipperOps.push(p("3660b", [6, 21, 0], "dark blue", 270));
collarAndFlipperOps.push(p("3003", [6, 24, -2], "medium azure", 0));
collarAndFlipperOps.push(p("3003", [6, 24, 0], "dark blue", 0));
collarAndFlipperOps.push(p("15068", [6, 27, -2], "dark blue", 270));
collarAndFlipperOps.push(p("15068", [6, 27, 0], "dark blue", 270));

collarAndFlipperOps.push(p("3660b", [7, 24, -3], "medium azure", 270));
collarAndFlipperOps.push(p("3660b", [7, 24, -1], "medium azure", 270));
collarAndFlipperOps.push(p("3003", [7, 27, -3], "medium azure", 0));
collarAndFlipperOps.push(p("3003", [7, 27, -1], "medium azure", 0));
collarAndFlipperOps.push(p("15068", [7, 30, -3], "medium azure", 270));
collarAndFlipperOps.push(p("15068", [7, 30, -1], "medium azure", 270));

collarAndFlipperOps.push(p("24201", [9, 27, -3], "medium azure", 270));
collarAndFlipperOps.push(p("24201", [9, 27, -2], "medium azure", 270));
collarAndFlipperOps.push(p("24201", [9, 27, -1], "medium azure", 270));
collarAndFlipperOps.push(p("15068", [9, 31, -3], "medium azure", 270));
collarAndFlipperOps.push(p("11477", [9, 31, -1], "medium azure", 270));
collarAndFlipperOps.push(p("25269", [9, 31, -4], "white", 270));
collarAndFlipperOps.push(p("24246", [10, 31, -4], "white", 0));

section("Piplup Cape Collar and Flippers", collarAndFlipperOps);

// ============================================================================
// SECTION 4: PIPLUP HEAD, 3-PRONGED CROWN, CONICAL BEAK & EYES (y = 31 .. 63)
// ============================================================================
const headOps = [box(HEAD_BOX)];

// Lower Head, Chin & Cheek Undercut (y = 31..36)
headOps.push(p("3660b", [-1, 31, -5], "white", 0));
headOps.push(...pMirrorX("3660b", [-3, 31, -5], "medium azure", 0));
headOps.push(...pMirrorX("24201", [-4, 31, -5], "medium azure", 0));
for (let z = -3; z <= 1; z += 2) {
  headOps.push(...pMirrorX("3660b", [-6, 31, z], "medium azure", 90));
  headOps.push(...pMirrorX("3660b", [-7, 34, z], "medium azure", 90));
}
for (let x = -4; x <= 2; x += 2) {
  headOps.push(p("3660b", [x, 31, 3], "dark blue", 180));
  headOps.push(p("3660b", [x, 34, 4], "blue", 180));
}
headOps.push(...pMirrorX("3665a", [-5, 34, 3], "blue", 180));

// Lower Cheeks in Medium Azure & White Chin under Beak (y = 34..37, z = -6..-4)
headOps.push(p("3001", [-2, 34, -5], "white", 0));
headOps.push(...pMirrorX("3003", [-4, 34, -5], "medium azure", 0));
headOps.push(...pMirrorX("15068", [-6, 34, -5], "medium azure", 90));
headOps.push(...pMirrorX("11477", [-6, 34, -3], "medium azure", 90));

// 3D Conical Yellow Beak (y = 35..43, z = -10..-5, x = -3..2)
// Lower Beak / Smiling Mouth (y = 35..37)
headOps.push(p("3660b", [-1, 35, -7], "bright light orange", 0));
headOps.push(...pMirrorX("3665a", [-2, 35, -7], "yellow", 0));
headOps.push(p("24201", [-1, 35, -9], "yellow", 0));
headOps.push(p("24201", [0, 35, -9], "yellow", 0));
headOps.push(p("3022", [-1, 37, -7], "bright light orange", 0));

// Upper Beak Cone (y = 38..43, z = -10..-5)
headOps.push(p("3001", [-2, 38, -6], "yellow", 0));
