{"tool": "brick.build", "input": {"seed": 1, "code": "script({
  title: "Piplup — Sinnoh Water-Type Starter",
  description: "Large-scale sculpted Piplup with 3-pronged light-blue crown, conical beak, white chest buttons, dark-blue cape & tail, waving flipper, Bubble Beam water vortex, Sinnoh ice crystals, and Poke Ball with Berries.",
  palette: {
    body: "medium azure",
    head: "blue",
    cape: "dark blue",
    belly: "white",
    beak: "yellow",
    foot: "bright light orange",
    eye: "black",
