feetOps.push(...pMirrorX("3023b", [-2, 0, -3], "bright light orange", 90));
feetOps.push(...pMirrorX("3020", [-6, 0, -1], "bright light orange", 0));
feetOps.push(...pMirrorX("3022", [-5, 0, 1], "bright light orange", 0));

// Three forward toes at z = -8 .. -6
