// Layer y = 1..3: Sculpted toes, rounded claws, and webbed instep slopes
feetOps.push(...pMirrorX("24246", [-7, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("54200", [-7, 1, -6], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-5, 1, -8], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-4, 1, -8], "yellow", 0));
feetOps.push(...pMirrorX("15068", [-5, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("24246", [-2, 1, -7], "yellow", 0));
feetOps.push(...pMirrorX("54200", [-2, 1, -6], "yellow", 0));

// Mid-foot arch & heel (y = 1..3)
feetOps.push(...pMirrorX("11477", [-7, 1, -5], "bright light orange", 0));
feetOps.push(...pMirrorX("11477", [-2, 1, -5], "bright light orange", 0));
feetOps.push(...pMirrorX("3003", [-5, 1, -4], "bright light orange", 0));
feetOps.push(...pMirrorX("3004", [-5, 1, -2], "bright light orange", 0));
feetOps.push(...pMirrorX("11477", [-6, 1, -3], "yellow", 90));
feetOps.push(...pMirrorX("11477", [-3, 1, -3], "yellow", 270));
feetOps.push(...pMirrorX("15068", [-5, 1, -1], "bright light orange", 180));
feetOps.push(...pMirrorX("3069b", [-5, 1, 1], "bright light orange", 0));

// Ankle columns & lower leg transition (y = 4..5)
feetOps.push(...pMirrorX("3660b", [-5, 3, -5], "medium azure", 0));
feetOps.push(...pMirrorX("3660b", [-6, 3, -3], "medium azure", 90));
feetOps.push(...pMirrorX("3660b", [-3, 3, -3], "medium azure", 270));
feetOps.push(...pMirrorX("3660b", [-5, 3, -1], "dark blue", 180));
feetOps.push(...pMirrorX("3022", [-5, 4, -3], "medium azure", 0));
feetOps.push(...pMirrorX("3022", [-5, 5, -3], "medium azure", 0));

section("Piplup Feet and Ankles", feetOps);

// ============================================================================
// SECTION 2: PIPLUP PLUMP TORSO, WHITE CHEST BUTTONS & TAIL CAPE (y = 6 .. 26)
// ============================================================================
const torsoOps = [box(TORSO_BOX)];

// Lower belly & hip undercut (y = 6..9)
for (let x = -4; x <= 2; x += 2) {
  torsoOps.push(p("3660b", [x, 6, -5], "medium azure", 0));
  torsoOps.push(p("3660b", [x, 6, 3], "dark blue", 180));
}
torsoOps.push(...pMirrorX("24201", [-5, 6, -5], "medium azure", 0));
torsoOps.push(...pMirrorX("24201", [-5, 6, 3], "dark blue", 180));
for (let z = -3; z <= 1; z += 2) {
  torsoOps.push(...pMirrorX("3660b", [-6, 6, z], "medium azure", 90));
}
// Crotch / lower belly bridge between legs at y = 5..8
torsoOps.push(p("3660b", [-1, 5, -4], "medium azure", 0));
torsoOps.push(p("3660b", [-1, 5, 0], "dark blue", 180));
torsoOps.push(p("15068", [-1, 4, -2], "medium azure", 0));

// Plump lower & mid belly front shell (y = 9..17, z = -6..-4)
